namespace RonSijm.FluidHumidifier.Factories.EVS;

public class EnvironmentFactory(string resourceName = null, Action<Humidifier.EVS.Environment> factoryAction = null) : ResourceFactory<Humidifier.EVS.Environment>(resourceName)
{

    internal List<InnerEnvironmentHostInfoForCreateFactory> HostsFactories { get; set; } = [];

    internal InnerEnvironmentLicenseInfoFactory LicenseInfoFactory { get; set; }

    internal InnerEnvironmentConnectivityInfoFactory ConnectivityInfoFactory { get; set; }

    internal InnerEnvironmentInitialVlansFactory InitialVlansFactory { get; set; }

    internal InnerEnvironmentServiceAccessSecurityGroupsFactory ServiceAccessSecurityGroupsFactory { get; set; }

    internal InnerEnvironmentVcfHostnamesFactory VcfHostnamesFactory { get; set; }

    protected override Humidifier.EVS.Environment Create()
    {
        var environmentResult = CreateEnvironment();
        factoryAction?.Invoke(environmentResult);

        return environmentResult;
    }

    private Humidifier.EVS.Environment CreateEnvironment()
    {
        var environmentResult = new Humidifier.EVS.Environment
        {
            GivenName = InputResourceName,
        };

        return environmentResult;
    }
    public override void CreateChildren(Humidifier.EVS.Environment result)
    {
        base.CreateChildren(result);

        result.Hosts = HostsFactories.Any() ? HostsFactories.Select(x => x.Build()).ToList() : null;
        result.LicenseInfo ??= LicenseInfoFactory?.Build();
        result.ConnectivityInfo ??= ConnectivityInfoFactory?.Build();
        result.InitialVlans ??= InitialVlansFactory?.Build();
        result.ServiceAccessSecurityGroups ??= ServiceAccessSecurityGroupsFactory?.Build();
        result.VcfHostnames ??= VcfHostnamesFactory?.Build();
    }

} // End Of Class

